def find_max_rectangles(grid, target_color):
    """Find the largest rectangular region of each color."""
    h, w = len(grid), len(grid[0])
    all_rects = []
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != target_color:
                continue

            # Find largest rectangular region starting at (r,c)
            # Extend right and down
            max_r, max_c = r, c

            # Find max row
            while max_r + 1 < h and grid[max_r+1][c] == target_color:
                max_r += 1

            # Find max col (but only if current row is that color)
            valid_cols = [c for col in range(w) if all(grid[r][col] == target_color for r in range(max(0, r), min(h, max_r+1)))]
            if not valid_cols:
                continue

            max_c = max(valid_cols)

            # Verify all cells in this region are target_color
            is_solid = True
            for rr in range(r, max_r + 1):
                for cc in range(c, max_c + 1):
                    if grid[rr][cc] != target_color:
                        is_solid = False
                        break
                if not is_solid:
                    break

            if is_solid:
                # Check if we already have a larger or equal region
                existing = None
                for ex_r, ex_c, ex_rr, ex_cc in all_rects:
                    if ex_r == r and ex_c == c:
                        existing = (ex_rr, ex_cc)
                        break

                if existing is None or (max_r, max_c) > existing:
                    all_rects.append((r, c, max_r, max_c))

    return all_rects

def fill_rectangles_flood(grid):
    """Fill rectangular frames based on parity, using flood fill."""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]  # Background is top-left color

    result = [row[:] for row in grid]

    # Background fill (keep paths escapeable)
    escaped = set()

    # Start flood from edge boundary cells that are background
    queue = deque()
    for r in range(h):
        if grid[r][0] == bg:
            queue.append((r, 0))
        if grid[r][w-1] == bg:
            queue.append((r, w-1))
    for c in range(w):
        if grid[0][c] == bg:
            queue.append((0, c))
        if grid[h-1][c] == bg:
            queue.append((h-1, c))

    # Also add all edge cells and their neighbors of bg color
    edge_cells = set()
    for r in range(min(h, 5)):
        for c in range(w):
            if grid[r][c] == bg:
                edge_cells.add((r, c))
    for c in range(min(w, 5)):
        for r in range(h):
            if grid[r][c] == bg:
                edge_cells.add((r, c))

    # Start from edge cells
    for r, c in edge_cells:
        if (r, c) not in escaped:
            queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        if (r, c) in escaped:
            continue
        escaped.add((r, c))
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr][nc] == bg and (nr, nc) not in escaped:
                    queue.append((nr, nc))

    # Now find rectangular frames (max rectangles of each color)
    colors = {c for c in row for row in grid if c != bg}

    # Add background as a "color" with potential to fill inner holes
    colors.add(bg)

    for color in sorted(colors):
        max_rects = find_max_rectangles(grid, color)

        for r, c, br, cc in max_rects:
            interior_h = br - r - 1
            interior_w = cc - c - 1

            # Calculate fill value
            if interior_h < 0 or interior_w < 0:
                continue

            if interior_h % 2 == 1 and interior_w % 2 == 1:
                fill = 7
            elif interior_h % 2 == 0 and interior_w % 2 == 0:
                fill = 2
            else:
                fill = None

            if fill is None:
                continue

            # Fill if interior cells are background and not escaped
            for rr in range(r+1, br):
                for cc in range(c+1, cc):
                    if (rr, cc) in escaped:
                        continue
                    if grid[rr][cc] == bg:
                        result[rr][cc] = fill

    return result

