from collections import deque
def find_components(grid, target_color):
    """Find connected components of target_color."""
    h, w = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == target_color and (r, c) not in visited:
                component = []
                q = deque([(r, c)])
                visited.add((r, c))
                while q:
                    rr, cc = q.popleft()
                    component.append((rr, cc))
                    for nr, nc in [(rr+1, cc), (rr-1, cc), (rr, cc+1), (rr, cc-1)]:
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == target_color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
                components.append(component)

    return components

def transform(grid):
    """Main transform function."""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    result = [row[:] for row in grid]

    # First: flood fill background cells that can reach edge
    escaped = set()
    queue = deque()

    # Add all background cells on edge
    for r in range(h):
        if grid[r][0] == bg and (r, 0) not in escaped:
            queue.append((r, 0))
            escaped.add((r, 0))
        if grid[r][w-1] == bg and (r, w-1) not in escaped:
            queue.append((r, w-1))
            escaped.add((r, w-1))
    for c in range(w):
        if grid[0][c] == bg and (0, c) not in escaped:
            queue.append((0, c))
            escaped.add((0, c))
        if grid[h-1][c] == bg and (h-1, c) not in escaped:
            queue.append((h-1, c))
            escaped.add((h-1, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in escaped and grid[nr][nc] == bg:
                    escaped.add((nr, nc))
                    queue.append((nr, nc))

    # Now process connected components of non-background colors
    visited_all = set()
    for color in sorted(set(c for row in grid for c in row if c != bg)):
        components = find_components(grid, color)
        for component in components:
            # Compute bbox
            rmin, cmin = min(r for r,c in component), min(c for r,c in component)
            rmax, cmax = max(r for r,c in component), max(c for r,c in component)

            # Check if it forms a solid rectangular region
            is_solid = all(grid[r][c] == color for r in range(rmin, rmax+1) for c in range(cmin, cmax+1))

            if not is_solid:
                continue

            int_h = rmax - rmin - 1
            int_w = cmax - cmin - 1

            if int_h <= 0 or int_w <= 0:
                continue  # Skip single cells/lines

            # Determine fill value
            if int_h % 2 == 1 and int_w % 2 == 1:
                fill = 7
            elif int_h % 2 == 0 and int_w % 2 == 0:
                fill = 2
            else:
                continue  # Skip mixed interiors

            # Fill background cells in bounding box that aren't escaped
            for r in range(rmin, rmax + 1):
                for c in range(cmin, cmax + 1):
                    if grid[r][c] == bg and (r, c) not in escaped:
                        result[r][c] = fill

    return result

