import json
from collections import deque

def find_components(grid, target_color):
    h, w = len(grid), len(grid[0])
    visited = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == target_color and (r, c) not in visited:
                comp = []
                q = deque([(r, c)])
                visited.add((r, c))
                while q:
                    rr, cc = q.popleft()
                    comp.append((rr, cc))
                    for nr, nc in [(rr+1, cc), (rr-1, cc), (rr, cc+1), (rr, cc-1)]:
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == target_color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
                components.append(comp)
    return components

def cell_adjacent_to_components(r, c, comp_map, check_dim='both'):
    """Get adjacency info for cell (r,c) to components."""
    horiz_comps = []
    vert_comps = []

    for dc in [(-1,0), (1,0)]:
        nc = c + dc[0]
        if 0 <= nc < len(comp_map[0]) and (r, nc) in comp_map:
            horiz_comps.append(comp_map[(r, nc)])

    for dr in [(-1,0), (1,0)]:
        nr = r + dr[0]
        if 0 <= nr < len(comp_map) and (nr, c) in comp_map:
            vert_comps.append(comp_map[(nr, c)])

    horiz_set = set(horiz_comps)
    vert_set = set(vert_comps)

    return horiz_comps, vert_comps, horiz_set, vert_set

